const BYTES: &[u8] = include_bytes!("../data/item_types_26_1.bin");
const ITEM_COUNT: usize = 1506;
const RECORDS_OFFSET: usize = 38081;
const RECORD_STRIDE: usize = 22;
const STRINGS_END: usize = RECORDS_OFFSET;

const _: () = {
    let mut i = 0;
    while i + 8 <= STRINGS_END {
        let word = u64::from_ne_bytes([
            BYTES[i],
            BYTES[i + 1],
            BYTES[i + 2],
            BYTES[i + 3],
            BYTES[i + 4],
            BYTES[i + 5],
            BYTES[i + 6],
            BYTES[i + 7],
        ]);
        assert!(word & 0x8080_8080_8080_8080 == 0);
        i += 8;
    }
    while i < STRINGS_END {
        assert!(BYTES[i] < 0x80);
        i += 1;
    }
};

macro_rules! u16_at {
    ($offset:expr) => {{
        let off = $offset;
        u16::from_le_bytes([BYTES[off], BYTES[off + 1]])
    }};
}

macro_rules! u32_at {
    ($offset:expr) => {{
        let off = $offset;
        u32::from_le_bytes([BYTES[off], BYTES[off + 1], BYTES[off + 2], BYTES[off + 3]])
    }};
}

macro_rules! str_at {
    ($offset:expr, $len:expr) => {{
        let off: usize = $offset;
        let len: usize = $len;
        assert!(off + len <= STRINGS_END);
        // SAFETY: `BYTES[..STRINGS_END]` is verified ASCII above and `off + len`
        // is bounded within `BYTES`.
        unsafe {
            core::str::from_utf8_unchecked(core::slice::from_raw_parts(
                BYTES.as_ptr().add(off),
                len,
            ))
        }
    }};
}

macro_rules! opt_str_at {
    ($offset:expr, $len:expr) => {{
        let len_u16: u16 = $len;
        if len_u16 == u16::MAX {
            None
        } else {
            Some(str_at!($offset, len_u16 as usize))
        }
    }};
}

